import{at as e,bt as t,o as n,ot as r}from"./chunks/framework.D9EW6sZo.js";var i=JSON.parse(`{"title":"个人净资产追踪使用指南","description":"使用个人净资产追踪工具维护资产、负债、外币汇率和分期项目，并通过本地、OneDrive 或 Google Drive 备份与恢复账本。","frontmatter":{"title":"个人净资产追踪使用指南","description":"使用个人净资产追踪工具维护资产、负债、外币汇率和分期项目，并通过本地、OneDrive 或 Google Drive 备份与恢复账本。"},"headers":[],"relativePath":"tools/net-worth-guide.md","filePath":"tools/net-worth-guide.md","lastUpdated":1786586539000}`),a={name:`tools/net-worth-guide.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="个人净资产追踪使用指南" tabindex="-1">个人净资产追踪使用指南 <a class="header-anchor" href="#个人净资产追踪使用指南" aria-label="Permalink to “个人净资产追踪使用指南”">​</a></h1><p>本指南介绍如何使用<a href="./net-worth.html">个人净资产追踪</a>记录各账户的月度余额，并查看资产、负债和净资产的变化。</p><div class="warning custom-block"><p class="custom-block-title">先备份再清理浏览器 账本默认保存在当前浏览器的 <code>IndexedDB</code> 中。清除本站数据、更换浏览器或设备前，请先在“备份”页下载账本，或手动备份到</p><p>OneDrive 或 Google Drive。</p></div><h2 id="适用范围" tabindex="-1">适用范围 <a class="header-anchor" href="#适用范围" aria-label="Permalink to “适用范围”">​</a></h2><p>这个工具适合记录：</p><ul><li>银行、券商、现金和数字资产等账户的月度总余额。</li><li>信用借款等需要手动更新余额的普通负债。</li><li>每月金额固定的分期负债。</li><li><code>CNY</code>、<code>USD</code>、<code>HKD</code> 和 <code>USDT</code> 账户及其人民币折算结果。</li></ul><p>它不是收支记账本或投资交易系统，不记录逐笔消费、转账、证券持仓和交易流水。</p><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to “快速开始”">​</a></h2><h3 id="_1-新增账户" tabindex="-1">1. 新增账户 <a class="header-anchor" href="#_1-新增账户" aria-label="Permalink to “1. 新增账户”">​</a></h3><p>打开<a href="./net-worth.html">个人净资产追踪</a>，点击“新增账户”，填写以下信息：</p><ul><li><strong>账户名称</strong>：建议包含机构和币种，例如“富途-USD”。</li><li><strong>类型</strong>：选择“资产”或“负债”。</li><li><strong>币种</strong>：一个账户只能使用一种币种；同一机构有多种币种时，应分别建立账户。</li><li><strong>开始月份</strong>：账户从该月起参与历史统计。</li><li><strong>初始余额</strong>：普通账户可以直接填写，也可以留空后再更新。</li><li><strong>负债形态</strong>：负债账户可选择“手动更新”或“分期负债”。</li></ul><p>机构、分类、地区和备注用于整理账户，不影响金额计算。</p><div class="tip custom-block"><p class="custom-block-title">账户产生余额记录后，类型、币种和负债形态不能直接修改，避免改变已有历史的含义。</p></div><h3 id="_2-更新普通账户余额" tabindex="-1">2. 更新普通账户余额 <a class="header-anchor" href="#_2-更新普通账户余额" aria-label="Permalink to “2. 更新普通账户余额”">​</a></h3><p>在“总览”页点击账户，再点击“更新余额”：</p><ol><li>选择统计月份。</li><li>输入该账户在该月的最终总余额，资产和负债都填写非负数。</li><li>外币账户确认自动获取的汇率，或手动修改汇率。</li><li>点击“保存余额”。</li></ol><p>同一账户在同一个月只保留一条余额记录，再次保存会覆盖当月旧值。没有变化的账户不需要每月重复录入；汇总会采用截至目标月份的最近一条记录。</p><h3 id="_3-查看总览和历史" tabindex="-1">3. 查看总览和历史 <a class="header-anchor" href="#_3-查看总览和历史" aria-label="Permalink to “3. 查看总览和历史”">​</a></h3><p>“总览”页显示：</p><ul><li>净资产、资产和负债合计。</li><li>当前资产账户的分布。</li><li>每个账户的原币余额、人民币金额和最后更新月份。</li></ul><p>“历史”页可以：</p><ul><li>查看净资产、总资产和总负债趋势。</li><li>选择月份，查看该月各账户的统计状态。</li><li>查看单个账户的全部月度记录和余额趋势。</li><li>修正或删除手工录入的历史记录。</li></ul><p>分期自动生成的余额不能直接修改或删除，需要通过分期项目的“修正”或“终止”操作处理。</p><h2 id="外币与汇率" tabindex="-1">外币与汇率 <a class="header-anchor" href="#外币与汇率" aria-label="Permalink to “外币与汇率”">​</a></h2><ul><li><code>CNY</code> 固定按汇率 <code>1</code> 计算。</li><li><code>USD</code> 和 <code>HKD</code> 会自动获取对应月份的人民币参考汇率。</li><li><code>USDT</code> 暂按同月 <code>USD/CNY</code> 汇率折算。</li><li>自动获取失败时，可以手动填写汇率。</li><li>汇率按“币种 + 月份”保存为快照，后续市场汇率变化不会自动改写历史。</li><li>缺少汇率的账户会显示提示，并暂时不计入人民币汇总。</li></ul><h2 id="管理分期负债" tabindex="-1">管理分期负债 <a class="header-anchor" href="#管理分期负债" aria-label="Permalink to “管理分期负债”">​</a></h2><h3 id="新增分期" tabindex="-1">新增分期 <a class="header-anchor" href="#新增分期" aria-label="Permalink to “新增分期”">​</a></h3><p>先新增一个“负债”类型、“分期负债”形态的账户，然后点击该账户并选择“添加分期”。每个项目需要填写：</p><ul><li>项目名称。</li><li>每期金额，可包含已确定的利息或费用。</li><li>原总期数和当前剩余期数。</li><li>下次还款月。</li></ul><p>项目的剩余应付总额按“每期金额 × 剩余期数”计算；同一分期账户可以包含多个项目，账户余额是所有未结束项目的合计。</p><h3 id="处理还款状态" tabindex="-1">处理还款状态 <a class="header-anchor" href="#处理还款状态" aria-label="Permalink to “处理还款状态”">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>处理方式</th></tr></thead><tbody><tr><td>本月待确认</td><td>确认扣款后点击“已还一期”；进入下个月仍未处理时，系统会按计划推定已还。</td></tr><tr><td>进行中</td><td>页面跨月打开时，会自动补记已经过去的计划月份。</td></tr><tr><td>已逾期</td><td>剩余金额继续计入负债，使用“修正”更新实际剩余期数，或终止项目。</td></tr><tr><td>已结清</td><td>剩余期数归零后保留历史，不再计入当前负债。</td></tr></tbody></table><p>如果实际扣款失败、延期或剩余期数不正确，使用“修正”并选择生效月份。合同发生变化时，终止旧项目后再新增项目。</p><p>只有当月误建且首个还款月尚未来到的项目可以删除；其他项目只能结清或终止。分期账户必须先处理完全部进行中或逾期项目，才能停用账户。</p><h2 id="备份与恢复" tabindex="-1">备份与恢复 <a class="header-anchor" href="#备份与恢复" aria-label="Permalink to “备份与恢复”">​</a></h2><h3 id="下载和上传账本" tabindex="-1">下载和上传账本 <a class="header-anchor" href="#下载和上传账本" aria-label="Permalink to “下载和上传账本”">​</a></h3><p>进入“备份”页，点击“下载当前账本”即可保存完整 JSON 文件。建议在集中更新账户后下载一次。</p><p>恢复时点击“上传账本文件”。页面会先显示导出时间、账户数、余额记录数和日期范围；确认后才会覆盖当前浏览器账本。覆盖前会保留最近一次本地回退，可以通过“恢复回退账本”撤销一次覆盖。</p><h3 id="onedrive-与-google-drive" tabindex="-1">OneDrive 与 Google Drive <a class="header-anchor" href="#onedrive-与-google-drive" aria-label="Permalink to “OneDrive 与 Google Drive”">​</a></h3><p>两个云端都是可选副本，不影响本地账本的日常使用。每次操作只涉及本地与当前选择的一个云端：</p><ul><li>“备份覆盖云端”使用当前本地账本覆盖云端副本。</li><li>“云端覆盖本地”先预览，再用云端账本替换本地。</li><li>“合并”按账户资料、账户月度余额、月度汇率和分期计划分别比较 <code>updatedAt</code>；较新记录获胜，时间相同采用云端版本，单边记录保留。</li><li>合并不会传播删除。需要让云端与本地删除结果完全一致时，请使用“备份覆盖云端”。</li></ul><p>OneDrive 使用可见的应用专属目录；Google Drive 使用“我的云端硬盘/个人净资产追踪”目录。两处目录都包含：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>README.txt</span></span>
<span class="line"><span>net-worth-ledger.json</span></span>
<span class="line"><span>history/YYYY/net-worth-ledger-YYYY-MM-DD.json</span></span></code></pre></div><p>Google Drive 仅申请 <code>drive.file</code> 权限，访问令牌只保留在当前浏览器会话；会话到期后需要重新连接。站点已内置 Google OAuth 客户端 ID，无需配置环境变量。部署到新域名时，需要在 Google Auth Platform 的 OAuth 客户端中添加该站点的“已获授权的 JavaScript 来源”。</p><h3 id="每日历史与恢复" tabindex="-1">每日历史与恢复 <a class="header-anchor" href="#每日历史与恢复" aria-label="Permalink to “每日历史与恢复”">​</a></h3><ul><li>本地账本每次成功变更都会刷新当天的 IndexedDB 历史版本。</li><li>云端账本内容实际变化时才刷新当天历史。</li><li>同一天最多保留一份，按设备本地日期命名，最新内容覆盖当天旧版本；历史不会自动清理。</li><li>恢复历史前会显示预览并保存一份本地回退；恢复只修改当前浏览器，不会自动写回云端。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>说明或处理方式</th></tr></thead><tbody><tr><td>换浏览器后看不到原账本</td><td>数据按浏览器本地保存，请在原浏览器下载账本，再到新浏览器上传。</td></tr><tr><td>外币账户没有计入净资产</td><td>该余额月份缺少汇率；在“历史”页找到记录并点击“补汇率”。</td></tr><tr><td>当月多次更新后只剩一条记录</td><td>这是月度快照规则，同一账户同一月份的新记录会覆盖旧记录。</td></tr><tr><td>分期余额无法直接修改</td><td>分期余额由项目汇总生成，请使用项目的“修正”“已还一期”或“终止”。</td></tr><tr><td>云端覆盖后想恢复原数据</td><td>在“备份”页点击“恢复回退账本”；系统只保留最近一次覆盖前的版本。</td></tr><tr><td>清除浏览器数据后账本丢失</td><td>本地数据无法由站点恢复，请上传之前下载的 JSON，或从已连接的云端恢复副本。</td></tr></tbody></table>`,48)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};